/* Corresponds to libjpeg 6b jcparam.c jpeg_quality_scaling (open-source IJG libjpeg 6b). Generated by km/libmatch.py: the upstream function with the declarations it uses, preprocessed, symbols renamed to the game's. */

int
jpeg_quality_scaling (int quality)

{

  if (quality <= 0) quality = 1;
  if (quality > 100) quality = 100;

  if (quality < 50)
    quality = 5000 / quality;
  else
    quality = 200 - quality*2;

  return quality;
}
